class Solution { private boolean valid(String s,int length){int[] target=new int[26],current=new int[26];for(int index=0;index<length;index++)target[s.charAt(index)-'a']++;for(int start=length;start<s.length();start+=length){Arrays.fill(current,0);for(int index=start;index<start+length;index++)current[s.charAt(index)-'a']++;if(!Arrays.equals(target,current))return false;}return true;}public int minAnagramLength(String s){for(int length=1;length<=s.length();length++)if(s.length()%length==0&&valid(s,length))return length;return s.length();} }
